// Bahasa Malaysia wording for the client PDF and the copy summary.
// tr(s) turns one English line written by the checks into Malay.
//   EXACT  fixed lines: [English, Malay]
//   RULES  lines with a number or a name inside: [pattern, Malay], where $1, $2 are the parts the pattern captured
// A line with no match is tried sentence by sentence; whatever still has no match stays in English, so a missing
// line never breaks a report. When a line in audit.js or analyze.js is reworded, update its twin here.
// Straight and curly quotes are treated as the same, so plain ' and " are fine in this file.
const N = s => String(s).replace(/[‘’]/g, "'").replace(/[“”]/g, '"');

