const MAP = new Map(EXACT.map(([en, my]) => [N(en), my]));
function one(s) {
  const k = N(s).trim();
  if (MAP.has(k)) return MAP.get(k);
  if (k.endsWith('.') && MAP.has(k.slice(0, -1))) return MAP.get(k.slice(0, -1)) + '.';
  for (const [re, to] of RULES) { const m = re.exec(k); if (m) return typeof to === 'function' ? to(m) : k.replace(re, to); }
  return null;
}
export function tr(s) {
  if (!s || typeof s !== 'string') return s;
  const hit = one(s);
  if (hit != null) return hit;
  const parts = N(s).split(/(?<=[.!?]) (?=[A-Z"])/);
  return parts.length > 1 ? parts.map(p => one(p) ?? p).join(' ') : s;
}
